const AGORA_TOKEN_API='https://angel-live-api.soulversepk.workers.dev/agora/token';type AgoraTokenResult={success?:boolean;appId?:string;appID?:string;token?:string;rtcToken?:string;channelName?:string;channel?:string;uid?:number|string;role?:string;expiresIn?:number;message?:string;error?:string};async function getAgoraToken(channelName:string,uid:number,role:'host'|'audience'){const roleVariants=[role];const bodies=roleVariants.map(rv=>({channelName,uid,role:rv}));let last='Agora token service unavailable';for(const body of bodies){try{const r=await fetch(AGORA_TOKEN_API,{method:'POST',headers:{accept:'application/json','content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json() as AgoraTokenResult;const appId=d.appId||d.appID;const token=d.token||d.rtcToken;if(r.ok&&appId&&token)return{success:true,appId,token,channelName:d.channelName||d.channel||channelName,uid:d.uid===undefined?uid:Number(d.uid),role,expiresIn:d.expiresIn||3600};last=d.message||d.error||('Token API HTTP '+r.status)}catch(e){last=e instanceof Error?e.message:last}}for(const rv of roleVariants){const u=new URL(AGORA_TOKEN_API);u.searchParams.set('channelName',channelName);u.searchParams.set('uid',String(uid));u.searchParams.set('role',rv);try{const r=await fetch(u.toString(),{headers:{accept:'application/json'}});const d=await r.json() as AgoraTokenResult;const appId=d.appId||d.appID;const token=d.token||d.rtcToken;if(r.ok&&appId&&token)return{success:true,appId,token,channelName:d.channelName||d.channel||channelName,uid:d.uid===undefined?uid:Number(d.uid),role,expiresIn:d.expiresIn||3600};last=d.message||d.error||('Token API HTTP '+r.status)}catch(e){last=e instanceof Error?e.message:last}}console.error('Agora token issue:',last);throw new Error(last)}
